const std = @import("std");
const posix = std.posix;

pub const Response = struct {
    status: u16,
    headers: std.StringHashMap([]const u8),
    body: []const u8,
    allocator: std.mem.Allocator,
    raw: []const u8,
    body_owned: bool,

    pub fn deinit(self: *Response) void {
        var it = self.headers.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*);
        }
        self.headers.deinit();
        if (self.body_owned) {
            self.allocator.free(self.body);
        }
        self.allocator.free(self.raw);
    }
};

fn containsHeaderControlCharacter(value: []const u8) bool {
    for (value) |c| {
        if (c == '\r' or c == '\n' or c == 0) return true;
    }
    return false;
}

const ParsedUrl = struct {
    host: []const u8,
    port: u16,
    path: []const u8,
    use_tls: bool,
};

fn parseUrl(allocator: std.mem.Allocator, url: []const u8) !ParsedUrl {
    var use_tls: bool = false;
    var default_port: u16 = 80;
    var rest: []const u8 = "";

    if (std.mem.startsWith(u8, url, "https://")) {
        use_tls = true;
        default_port = 443;
        rest = url["https://".len..];
    } else if (std.mem.startsWith(u8, url, "http://")) {
        use_tls = false;
        default_port = 80;
        rest = url["http://".len..];
    } else {
        return error.InvalidUrl;
    }

    if (rest.len == 0) return error.InvalidUrl;

    const path_start = std.mem.indexOfScalar(u8, rest, '/') orelse rest.len;
    const authority = rest[0..path_start];
    const path_part = if (path_start < rest.len) rest[path_start..] else "/";

    var host_slice: []const u8 = authority;
    var port = default_port;

    if (authority.len > 0 and authority[0] == '[') {
        const close_bracket = std.mem.indexOfScalar(u8, authority, ']') orelse return error.InvalidUrl;
        host_slice = authority[1..close_bracket];
        if (close_bracket + 1 < authority.len) {
            if (authority[close_bracket + 1] != ':') return error.InvalidUrl;
            const port_str = authority[close_bracket + 2 ..];
            if (port_str.len == 0) return error.InvalidUrl;
            port = try std.fmt.parseInt(u16, port_str, 10);
        }
    } else if (std.mem.indexOfScalar(u8, authority, ':')) |colon_idx| {
        host_slice = authority[0..colon_idx];
        const port_str = authority[colon_idx + 1 ..];
        if (port_str.len == 0) return error.InvalidUrl;
        port = try std.fmt.parseInt(u16, port_str, 10);
    }

    if (host_slice.len == 0) return error.InvalidUrl;
    if (containsHeaderControlCharacter(host_slice)) return error.InvalidUrl;
    if (containsHeaderControlCharacter(path_part)) return error.InvalidUrl;

    const host_copy = try allocator.dupe(u8, host_slice);
    errdefer allocator.free(host_copy);
    const path_copy = try allocator.dupe(u8, path_part);

    return ParsedUrl{
        .host = host_copy,
        .port = port,
        .path = path_copy,
        .use_tls = use_tls,
    };
}

fn resolveUrl(allocator: std.mem.Allocator, base_host: []const u8, base_port: u16, base_tls: bool, location: []const u8) !ParsedUrl {
    if (std.mem.startsWith(u8, location, "http://") or std.mem.startsWith(u8, location, "https://")) {
        return parseUrl(allocator, location);
    }
    const path_copy = if (location.len > 0 and location[0] == '/')
        try allocator.dupe(u8, location)
    else
        try std.fmt.allocPrint(allocator, "/{s}", .{location});

    return ParsedUrl{
        .host = try allocator.dupe(u8, base_host),
        .port = base_port,
        .path = path_copy,
        .use_tls = base_tls,
    };
}

pub const HttpClient = struct {
    allocator: std.mem.Allocator,
    host: []const u8,
    port: u16,
    path: []const u8,
    use_tls: bool,
    timeout_ms: u64,
    max_redirects: u8,
    http_version: []const u8,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator, url: []const u8, timeout_ms: u64) !Self {
        const parsed = try parseUrl(allocator, url);
        return Self{
            .allocator = allocator,
            .host = parsed.host,
            .port = parsed.port,
            .path = parsed.path,
            .use_tls = parsed.use_tls,
            .timeout_ms = timeout_ms,
            .max_redirects = 5,
            .http_version = "HTTP/1.1",
        };
    }

    pub fn deinit(self: *Self) void {
        self.allocator.free(self.host);
        self.allocator.free(self.path);
    }

    pub fn get(self: *Self, req_path: []const u8, headers: []const []const u8) !Response {
        return self.request("GET", req_path, null, "application/octet-stream", headers);
    }

    pub fn post(self: *Self, req_path: []const u8, body: []const u8, content_type: []const u8, headers: []const []const u8) !Response {
        return self.request("POST", req_path, body, content_type, headers);
    }

    pub fn request(
        self: *Self,
        method: []const u8,
        req_path: []const u8,
        body: ?[]const u8,
        content_type: []const u8,
        extra_headers: []const []const u8,
    ) !Response {
        var current_host = try self.allocator.dupe(u8, self.host);
        var current_path = try self.allocator.dupe(u8, if (req_path.len > 0) req_path else self.path);
        var current_port = self.port;
        var current_tls = self.use_tls;

        defer {
            self.allocator.free(current_host);
            self.allocator.free(current_path);
        }

        var redirects: u8 = 0;
        while (redirects <= self.max_redirects) : (redirects += 1) {
            var response = try self.execute(current_host, current_port, current_path, current_tls, method, body, content_type, extra_headers);

            if (response.status == 301 or response.status == 302 or response.status == 303 or response.status == 307 or response.status == 308) {
                if (response.headers.get("location")) |loc| {
                    const next_url = try resolveUrl(self.allocator, current_host, current_port, current_tls, loc);
                    self.allocator.free(current_host);
                    self.allocator.free(current_path);
                    current_host = next_url.host;
                    current_port = next_url.port;
                    current_path = next_url.path;
                    current_tls = next_url.use_tls;
                    response.deinit();
                    continue;
                }
            }
            return response;
        }
        return error.TooManyRedirects;
    }

    fn execute(
        self: *Self,
        host: []const u8,
        port: u16,
        req_path: []const u8,
        use_tls: bool,
        method: []const u8,
        body: ?[]const u8,
        content_type: []const u8,
        extra_headers: []const []const u8,
    ) !Response {
        if (extra_headers.len % 2 != 0) return error.InvalidHeaders;
        if (containsHeaderControlCharacter(method)) return error.InvalidMethod;

        var req_buffer = std.ArrayList(u8).init(self.allocator);
        defer req_buffer.deinit();

        const writer = req_buffer.writer();
        try writer.print("{s} {s} {s}\r\n", .{ method, req_path, self.http_version });
        try writer.print("Host: {s}\r\n", .{host});
        try writer.writeAll("User-Agent: SearchPlatformBot/0.2\r\n");
        try writer.writeAll("Accept-Encoding: gzip, deflate\r\n");

        if (body) |b| {
            if (containsHeaderControlCharacter(content_type)) return error.InvalidContentType;
            try writer.print("Content-Type: {s}\r\n", .{content_type});
            try writer.print("Content-Length: {d}\r\n", .{b.len});
        }

        var header_idx: usize = 0;
        while (header_idx < extra_headers.len) : (header_idx += 2) {
            const k = extra_headers[header_idx];
            const v = extra_headers[header_idx + 1];
            if (containsHeaderControlCharacter(k) or containsHeaderControlCharacter(v)) return error.InvalidHeader;
            try writer.print("{s}: {s}\r\n", .{ k, v });
        }

        try writer.writeAll("Connection: close\r\n\r\n");
        if (body) |b| try writer.writeAll(b);

        var resp_buffer = std.ArrayList(u8).init(self.allocator);
        errdefer resp_buffer.deinit();

        if (use_tls) {
            try self.transferTls(host, port, req_buffer.items, &resp_buffer);
        } else {
            try self.transferPlain(host, port, req_buffer.items, &resp_buffer);
        }

        const raw = try resp_buffer.toOwnedSlice();
        errdefer self.allocator.free(raw);

        return try self.parseHttpResponse(raw);
    }

    fn connectSocket(self: *Self, host: []const u8, port: u16) !posix.socket_t {
        const list = try std.net.getAddressList(self.allocator, host, port);
        defer list.deinit();
        if (list.addrs.len == 0) return error.NoAddressesFound;

        var last_err: anyerror = error.ConnectionRefused;

        for (list.addrs) |addr| {
            const fd = posix.socket(addr.any.family, posix.SOCK.STREAM, posix.IPPROTO.TCP) catch |err| {
                last_err = err;
                continue;
            };

            const timeout_secs = self.timeout_ms / 1000;
            const timeout_micros = (self.timeout_ms % 1000) * 1000;
            const timeout: posix.timeval = if (@hasField(posix.timeval, "sec"))
                .{ .sec = @intCast(timeout_secs), .usec = @intCast(timeout_micros) }
            else
                .{ .tv_sec = @intCast(timeout_secs), .tv_usec = @intCast(timeout_micros) };

            posix.setsockopt(fd, posix.SOL.SOCKET, posix.SO.RCVTIMEO, std.mem.asBytes(&timeout)) catch {};
            posix.setsockopt(fd, posix.SOL.SOCKET, posix.SO.SNDTIMEO, std.mem.asBytes(&timeout)) catch {};

            posix.connect(fd, &addr.any, addr.getOsSockLen()) catch |err| {
                posix.close(fd);
                last_err = err;
                continue;
            };

            return fd;
        }
        return last_err;
    }

    fn transferPlain(self: *Self, host: []const u8, port: u16, payload: []const u8, out: *std.ArrayList(u8)) !void {
        const fd = try self.connectSocket(host, port);
        defer posix.close(fd);

        var total: usize = 0;
        while (total < payload.len) {
            const written = try posix.write(fd, payload[total..]);
            if (written == 0) return error.WriteFailed;
            total += written;
        }

        var buf: [8192]u8 = undefined;
        while (true) {
            const n = posix.read(fd, &buf) catch |err| switch (err) {
                error.WouldBlock => return error.Timeout,
                error.ConnectionResetByPeer => break,
                else => return err,
            };
            if (n == 0) break;
            try out.appendSlice(buf[0..n]);
            if (out.items.len > 20 * 1024 * 1024) return error.ResponseTooLarge;
        }
    }

    fn transferTls(self: *Self, host: []const u8, port: u16, payload: []const u8, out: *std.ArrayList(u8)) !void {
        const fd = try self.connectSocket(host, port);
        defer posix.close(fd);

        var stream = std.net.Stream{ .handle = fd };
        var bundle = std.crypto.Certificate.Bundle{};
        defer bundle.deinit(self.allocator);
        try bundle.rescan(self.allocator);

        var tls_client = try std.crypto.tls.Client.init(stream, .{
            .host = .{ .explicit = host },
            .ca = .{ .bundle = bundle },
        });

        try tls_client.writeAll(stream, payload);

        var buf: [8192]u8 = undefined;
        while (true) {
            const n = tls_client.read(stream, &buf) catch |err| switch (err) {
                error.TlsConnectionTruncated => break,
                error.ConnectionResetByPeer => break,
                else => return err,
            };
            if (n == 0) break;
            try out.appendSlice(buf[0..n]);
            if (out.items.len > 20 * 1024 * 1024) return error.ResponseTooLarge;
        }
    }

    fn parseHttpResponse(self: *Self, data: []const u8) !Response {
        const header_end = std.mem.indexOf(u8, data, "\r\n\r\n") orelse return error.InvalidResponse;
        const header_block = data[0..header_end];

        var headers = std.StringHashMap([]const u8).init(self.allocator);
        errdefer {
            var it = headers.iterator();
            while (it.next()) |entry| {
                self.allocator.free(entry.key_ptr.*);
                self.allocator.free(entry.value_ptr.*);
            }
            headers.deinit();
        }

        var lines = std.mem.splitSequence(u8, header_block, "\r\n");
        const first_line = lines.next() orelse return error.InvalidResponse;
        var parts = std.mem.splitScalar(u8, first_line, ' ');
        _ = parts.next() orelse return error.InvalidResponse;
        const status_str = parts.next() orelse return error.InvalidResponse;
        const status = try std.fmt.parseInt(u16, std.mem.trim(u8, status_str, " "), 10);

        while (lines.next()) |line| {
            if (line.len == 0) continue;
            const colon_idx = std.mem.indexOfScalar(u8, line, ':') orelse continue;
            const key = std.mem.trim(u8, line[0..colon_idx], " \t");
            const value = std.mem.trim(u8, line[colon_idx + 1 ..], " \t");
            if (key.len == 0) continue;

            const key_owned = try self.allocator.dupe(u8, key);
            errdefer self.allocator.free(key_owned);
            for (key_owned) |*ch| ch.* = std.ascii.toLower(ch.*);

            const val_owned = try self.allocator.dupe(u8, value);
            errdefer self.allocator.free(val_owned);

            if (headers.fetchRemove(key_owned)) |old| {
                self.allocator.free(old.key);
                self.allocator.free(old.value);
            }
            try headers.put(key_owned, val_owned);
        }

        var body_slice = data[header_end + 4 ..];
        var is_chunked = false;
        var content_encoding: ?[]const u8 = null;

        if (headers.get("transfer-encoding")) |te| {
            if (std.ascii.indexOfIgnoreCase(te, "chunked") != null) {
                is_chunked = true;
            }
        }
        if (headers.get("content-encoding")) |ce| {
            content_encoding = ce;
        }

        var body: []const u8 = body_slice;
        var body_owned = false;

        if (is_chunked) {
            const dechunked = try decodeChunked(body_slice, self.allocator);
            body = dechunked;
            body_owned = true;
        }

        errdefer if (body_owned) self.allocator.free(body);

        if (content_encoding) |enc| {
            const trimmed = std.mem.trim(u8, enc, " \t");
            if (std.ascii.eqlIgnoreCase(trimmed, "gzip") or std.ascii.eqlIgnoreCase(trimmed, "x-gzip")) {
                const decompressed = try self.decompressGzip(body);
                if (body_owned) self.allocator.free(body);
                body = decompressed;
                body_owned = true;
            } else if (std.ascii.eqlIgnoreCase(trimmed, "deflate")) {
                const decompressed = try self.decompressZlib(body);
                if (body_owned) self.allocator.free(body);
                body = decompressed;
                body_owned = true;
            }
        }

        return Response{
            .status = status,
            .headers = headers,
            .body = body,
            .allocator = self.allocator,
            .raw = data,
            .body_owned = body_owned,
        };
    }

    fn decompressGzip(self: *Self, data: []const u8) ![]u8 {
        var in_stream = std.io.fixedBufferStream(data);
        var decompressor = std.compress.gzip.decompressor(in_stream.reader());
        return try decompressor.reader().readAllAlloc(self.allocator, 50 * 1024 * 1024);
    }

    fn decompressZlib(self: *Self, data: []const u8) ![]u8 {
        var in_stream = std.io.fixedBufferStream(data);
        var decompressor = std.compress.zlib.decompressor(in_stream.reader());
        const result = decompressor.reader().readAllAlloc(self.allocator, 50 * 1024 * 1024) catch {
            var in2 = std.io.fixedBufferStream(data);
            var decompressor2 = std.compress.flate.decompressor(in2.reader());
            return try decompressor2.reader().readAllAlloc(self.allocator, 50 * 1024 * 1024);
        };
        return result;
    }
};

fn decodeChunked(data: []const u8, allocator: std.mem.Allocator) ![]u8 {
    var out = std.ArrayList(u8).init(allocator);
    errdefer out.deinit();

    var index: usize = 0;
    while (true) {
        const line_end = std.mem.indexOfPos(u8, data, index, "\r\n") orelse return error.InvalidChunkedEncoding;
        var size_line = data[index..line_end];
        if (std.mem.indexOfScalar(u8, size_line, ';')) |semi| {
            size_line = size_line[0..semi];
        }
        size_line = std.mem.trim(u8, size_line, " \t");
        if (size_line.len == 0) return error.InvalidChunkedEncoding;

        const chunk_size = try std.fmt.parseInt(usize, size_line, 16);
        index = line_end + 2;

        if (chunk_size == 0) break;

        if (index + chunk_size > data.len) return error.InvalidChunkedEncoding;
        try out.appendSlice(data[index .. index + chunk_size]);
        index += chunk_size;

        if (index + 2 > data.len) return error.InvalidChunkedEncoding;
        if (!std.mem.eql(u8, data[index .. index + 2], "\r\n")) return error.InvalidChunkedEncoding;
        index += 2;
    }
    return out.toOwnedSlice();
}

pub fn fetch(allocator: std.mem.Allocator, url: []const u8, timeout_ms: u64) !Response {
    var client = try HttpClient.init(allocator, url, timeout_ms);
    defer client.deinit();
    return client.get(client.path, &[_][]const u8{});
}

